From b12c5b53e563908174de350b382aaf8a59d2ec23 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:25:15 +0100
Subject: [PATCH] shell/panelview: don't move events that land on an applet in
 the padding

Events in the panel's padding were moved inside the content area even
when an applet reached into it, so Pager rows near the edges got clicks
meant for the gaps between rows. Events on applets now stay in place.

BUG: 521271
---
 shell/panelview.cpp | 16 ++++++++++++++--
 1 file changed, 14 insertions(+), 2 deletions(-)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..834e18143a 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -1340,8 +1340,20 @@ bool PanelView::containmentContainsPosition(const QPointF &point) const
     // boundingRect.x() + boundingRect.width() to be part of the rectangle,
     // but the right/bottom-most pixels do not react to user input. Thus, we
     // manually exclude them here.
-    return (point.x() >= boundingRect.x() && point.x() < (boundingRect.x() + boundingRect.width()) && point.y() >= boundingRect.y()
-            && point.y() < (boundingRect.y() + boundingRect.height()));
+    if (point.x() >= boundingRect.x() && point.x() < (boundingRect.x() + boundingRect.width()) && point.y() >= boundingRect.y()
+        && point.y() < (boundingRect.y() + boundingRect.height())) {
+        return true;
+    }
+
+    // Applets can reach into the padding; events on them must stay in place
+    const auto applets = containment()->applets();
+    return std::any_of(applets.cbegin(), applets.cend(), [&point](Plasma::Applet *applet) {
+        if (!PlasmaQuick::AppletQuickItem::hasItemForApplet(applet)) {
+            return false;
+        }
+        QQuickItem *appletItem = PlasmaQuick::AppletQuickItem::itemForApplet(applet);
+        return appletItem->isVisible() && appletItem->contains(appletItem->mapFromScene(point));
+    });
 }

 QPointF PanelView::positionAdjustedForContainment(const QPointF &point) const
